/* render a people grid + bio dialog */
window.renderPeople = function (el, list, role) {
  el.innerHTML = list.map(function (p, idx) {
    return '<button class="person" data-i="' + idx + '"' + (p.y ? ' data-y="' + p.y + '"' : '') + '>' +
      '<span class="av"><span class="ini">' + initials(p.n) + '</span><img src="' + R(p.i) + '" alt="" loading="lazy"></span>' +
      '<span class="nm">' + esc(p.n) + '</span>' + (p.y ? '<span class="rl">Intake ' + p.y + '</span>' : '') + '</button>';
  }).join('');
  el.addEventListener('click', function (e) {
    var b = e.target.closest('.person'); if (!b) return;
    var p = list[+b.getAttribute('data-i')];
    openDialog('<div class="top"><span class="av"><span class="ini">' + initials(p.n) + '</span><img src="' + R(p.i) + '" alt=""></span><div><span class="role">' + role + (p.y ? ' · Intake ' + p.y : '') + '</span><h2>' + esc(p.n) + '</h2></div></div>' +
      '<div class="bd">' + p.b.map(function (t) { return '<p>' + esc(t) + '</p>'; }).join('') +
      (p.l && p.l.length ? '<div class="links">' + p.l.map(function (l) { return '<a href="' + esc(l[1]) + '" target="_blank" rel="noopener">' + esc(l[0]) + ' ↗</a>'; }).join('') + '</div>' : '') + '</div>');
  });
};
